import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.1lR7qgqY.js";const k=JSON.parse('{"title":"第 9 章 三種參考架構","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/09-architectures.md","filePath":"deploy/09-architectures.md","lastUpdated":1793001879000}'),l={name:"deploy/09-architectures.md"};function e(p,s,d,r,o,h){return t(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="第-9-章-三種參考架構" tabindex="-1">第 9 章 三種參考架構 <a class="header-anchor" href="#第-9-章-三種參考架構" aria-label="Permalink to &quot;第 9 章 三種參考架構&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ● 必要</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: 記憶體與磁碟占用為研究 2 的推論值, 實機驗證前請視為推估值</li></ul></div><p><strong>結論</strong>: 依人數與需求分三種組合, 由小到大逐步加層. 單人單機用最小組合; 2 至 10 人且需要檢索, 用標準組合; 多人, 多模型且有人每週維運 (並符合第 10.1 節條件), 才採進階組合.</p><table tabindex="0"><thead><tr><th>組合</th><th>適用</th><th>建議硬體等級</th><th>額外占用 (推論)</th></tr></thead><tbody><tr><td>最小安全組合</td><td>單人, 單機</td><td>A 至 F</td><td>介面約 0.5 至 1.5GB 記憶體; 磁碟約 2 至 5GB (不含模型)</td></tr><tr><td>標準組合</td><td>家庭或小團隊 2 至 10 人, 含檢索與基本評估</td><td>B, D, E; C 級須為中高記憶體款</td><td>嵌入模型約 0.6 至 1.2GB; 向量庫約 1 至 2GB; 磁碟約 10 至 30GB</td></tr><tr><td>進階組合</td><td>多人, 多模型, 含閘道, 代理與沙箱</td><td>F</td><td>閘道加 PostgreSQL 約 1 至 2GB; 磁碟約 50 至 100GB</td></tr></tbody></table><p>資料來源: 研究 2 (2026-10-26), 占用值由各元件公開資料加總推算, 信心: 中.</p><h2 id="_9-1-最小安全組合-單人-單機" tabindex="-1">9.1 最小安全組合 (單人, 單機) <a class="header-anchor" href="#_9-1-最小安全組合-單人-單機" aria-label="Permalink to &quot;9.1 最小安全組合 (單人, 單機)&quot;">​</a></h2><p><strong>元件</strong>: 推論引擎 (llama.cpp 或 Ollama), 加上一個介面. 等級 A 與 C 建議用 AnythingLLM 桌面版, 其他等級用 Open WebUI 單一容器. 不加閘道, 代理框架與 MCP.</p><p><strong>啟動順序</strong>: 推論引擎 → 介面.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[瀏覽器 / 桌面 App]</span></span>
<span class="line"><span>      | http://127.0.0.1:3000</span></span>
<span class="line"><span>      v</span></span>
<span class="line"><span>[Open WebUI 或 AnythingLLM] ----&gt; [Ollama / llama-server]</span></span>
<span class="line"><span>      |</span></span>
<span class="line"><span>   (本機資料卷: 對話, 設定) --&gt; 每週備份</span></span>
<span class="line"><span>   對外: 無開放連接埠</span></span></code></pre></div><h3 id="_9-1-1-用-docker-執行介面時的連接埠與位址" tabindex="-1">9.1.1 用 Docker 執行介面時的連接埠與位址 <a class="header-anchor" href="#_9-1-1-用-docker-執行介面時的連接埠與位址" aria-label="Permalink to &quot;9.1.1 用 Docker 執行介面時的連接埠與位址&quot;">​</a></h3><p>用容器跑介面時, 有兩件事容易做錯 (指令未實機驗證, 依下列官方文件整理):</p><ol><li><strong>發布連接埠時要指定 127.0.0.1.</strong> Docker 官方文件指出, <code>-p 8080:80</code> 會綁定在主機的任一位址, 要限制只有主機本身能存取, 須寫成 <code>-p 127.0.0.1:8080:80</code> (來源: Docker 文件 Port publishing and mapping). 此外, Docker 官方文件說明 Docker 與 ufw 的防火牆規則運作方式不相容, 已發布的連接埠可能不受 ufw 規則限制 (來源: Docker 文件 Packet filtering and firewalls). 因此「用 ufw 擋住」不能當作唯一防線, 發布時就要綁定 127.0.0.1.</li><li><strong>容器內的 127.0.0.1 指的是容器自己.</strong> 要從容器連到主機上的 Ollama, Open WebUI 官方文件建議使用 <code>host.docker.internal</code>, 並在 Linux 加上 <code>--add-host=host.docker.internal:host-gateway</code> (來源: Open WebUI 文件 Quick Start).</li></ol><p>範例 (以 Open WebUI 官方 Quick Start 的指令為基礎, 僅把發布位址改為 127.0.0.1, 並固定版本標籤):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> 127.0.0.1:3000:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#F47067;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">  --add-host=host.docker.internal:host-gateway</span><span style="--shiki-light:#005CC5;--shiki-dark:#F47067;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> open-webui:/app/backend/data</span><span style="--shiki-light:#005CC5;--shiki-dark:#F47067;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> WEBUI_SECRET_KEY=&quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> rand </span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">-hex</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> 32</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">)&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#F47067;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> open-webui</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> --restart</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> always</span><span style="--shiki-light:#005CC5;--shiki-dark:#F47067;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">  ghcr.io/open-webui/open-webui:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">固定版本標</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">籤</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&gt;</span></span></code></pre></div><p><code>WEBUI_SECRET_KEY</code> 請存入 <code>.env</code> 並沿用, 否則重建容器後所有人須重新登入 (來源: Open WebUI Quick Start). 官方範例使用浮動的 <code>:main</code> 標籤, 本手冊建議改用固定版本 (見第 19 章).</p><p><strong>尚待實機驗證的取捨 (推論, 信心: 中高)</strong>: Ollama 預設只綁 127.0.0.1:11434 (來源: Ollama FAQ). 在 Linux 上, 容器經 <code>host-gateway</code> 連主機時, 流量不是從主機的 127.0.0.1 進入, 因此預設設定下可能連不到. 常見解法有三種, 各有取捨:</p><table tabindex="0"><thead><tr><th>做法</th><th>作法</th><th>風險</th></tr></thead><tbody><tr><td>讓 Ollama 也跑在容器, 與介面共用 Docker 網路</td><td>不發布 Ollama 的連接埠</td><td>最單純; 需設定 GPU 直通 (依 Ollama 與 Docker 官方文件)</td></tr><tr><td>把 <code>OLLAMA_HOST</code> 改為 <code>0.0.0.0:11434</code></td><td>以 systemd 設定 (見第 8 章)</td><td>區域網路內其他裝置也連得到 11434, 須搭配主機防火牆</td></tr><tr><td>介面容器改用主機網路 (<code>--network=host</code>)</td><td>不經 Docker NAT</td><td>容器與主機共用網路, 隔離變弱</td></tr></tbody></table><p>建議優先採用第一種. 若採第二種, 請確認防火牆規則在 Docker 之外也有效, 並以另一台裝置實際掃描 11434 連接埠.</p><p><strong>安全基線檢核表</strong></p><ul><li>[ ] 所有服務只綁 127.0.0.1</li><li>[ ] 映像或安裝版本已記錄並鎖定</li><li>[ ] 介面已設管理者密碼, 並關閉公開註冊</li><li>[ ] 每週備份資料卷</li><li>[ ] 每週檢查一次安全公告, 每月評估一次是否升級 (見第 19, 20 章)</li><li>[ ] 不在介面中存放雲端 API 金鑰, 或只放低額度金鑰</li></ul><h2 id="_9-2-標準組合-家庭或小團隊" tabindex="-1">9.2 標準組合 (家庭或小團隊) <a class="header-anchor" href="#_9-2-標準組合-家庭或小團隊" aria-label="Permalink to &quot;9.2 標準組合 (家庭或小團隊)&quot;">​</a></h2><p><strong>元件</strong>:</p><ul><li>推論引擎, 搭配 llama-swap (需要多模型輪替時)</li><li>介面: Open WebUI 或 LibreChat</li><li>嵌入模型: Qwen3-Embedding-0.6B 或 bge-m3</li><li>向量庫: 介面內建的, 或 Qdrant</li><li>文件解析: Docling</li><li>評估: promptfoo 測試集 (第 14 章)</li><li>網路: Tailscale</li></ul><p><strong>啟動順序</strong>: 推論引擎 / llama-swap → 向量庫 → 介面 → (排程) 文件解析與匯入 → promptfoo 驗證.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[家人 / 同事裝置] --Tailscale (WireGuard)--&gt; [主機 100.x.y.z]</span></span>
<span class="line"><span>                                              |</span></span>
<span class="line"><span>                     +------------------------+-----------------+</span></span>
<span class="line"><span>                     v                        v                 v</span></span>
<span class="line"><span>               [Open WebUI / LibreChat]  [Qdrant :6333]    [Docling 批次]</span></span>
<span class="line"><span>                     |  (內部 Docker 網路, 不對外)</span></span>
<span class="line"><span>                     v</span></span>
<span class="line"><span>               [llama-swap :8080] --&gt; [llama-server: 對話模型 / 嵌入模型]</span></span>
<span class="line"><span>   公網: 無連接埠轉發</span></span></code></pre></div><p><strong>在最小組合的檢核表之上, 另加</strong>:</p><ul><li>[ ] 以 Tailscale ACL 限定可連入的裝置</li><li>[ ] 每位使用者使用個別帳號</li><li>[ ] RAG 文件來源只限可信資料夾 (對應 OWASP LLM08 與 ASI06, 見第 11.4 節)</li><li>[ ] 升級前先跑 promptfoo 測試集</li><li>[ ] <code>.env</code> 權限設為 600</li></ul><h2 id="_9-3-進階組合-多人-多模型-◇" tabindex="-1">9.3 進階組合 (多人, 多模型) ◇ <a class="header-anchor" href="#_9-3-進階組合-多人-多模型-◇" aria-label="Permalink to &quot;9.3 進階組合 (多人, 多模型) ◇&quot;">​</a></h2><p><strong>使用條件</strong>: 有人能每週維運, 且符合第 10.1 節列出的閘道條件. 若不符, 請回到 9.2.</p><p><strong>元件</strong>: 標準組合全部, 加上:</p><ul><li>閘道: LiteLLM 或 Bifrost 擇一, 以映像摘要值 (digest) 鎖定版本</li><li>Caddy (HTTPS)</li><li>代理: LangGraph 程式庫, 嵌入自己撰寫的服務</li><li>沙箱化的程式碼執行容器</li><li>少量已審核, 已容器化的 MCP 伺服器</li><li>可選: Langfuse (另備至少 12GB 記憶體給 ClickHouse 與 Redis 等), Prompt Guard 2 22M</li></ul><p><strong>啟動順序</strong>: PostgreSQL / Redis → 推論 / llama-swap → 閘道 → 向量庫 → MCP 伺服器 (容器) → 代理服務 → 介面 → Caddy → 可觀測性.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[使用者] --Tailscale--&gt; [Caddy :443 (TLS, 基本驗證, 速率限制)]</span></span>
<span class="line"><span>                              |</span></span>
<span class="line"><span>                              v</span></span>
<span class="line"><span>                       [介面 (SSO 可選)]</span></span>
<span class="line"><span>                              |</span></span>
<span class="line"><span>                              v</span></span>
<span class="line"><span>        [代理服務 (LangGraph)] ---&gt; [閘道 LiteLLM / Bifrost (內網, 管理路徑封鎖)]</span></span>
<span class="line"><span>             |        |                         |</span></span>
<span class="line"><span>             |        |                         v</span></span>
<span class="line"><span>             |        |                   [llama-swap -&gt; 推論引擎]</span></span>
<span class="line"><span>             |        v</span></span>
<span class="line"><span>             |   [MCP 伺服器容器: 非 root, 唯讀, 限制對外連線, 只掛指定資料夾]</span></span>
<span class="line"><span>             v</span></span>
<span class="line"><span>      [程式碼沙箱: --network none, rootless / gVisor]</span></span>
<span class="line"><span>      [Langfuse (可選) &lt;- OTel 追蹤]</span></span></code></pre></div><p><strong>在前兩組的檢核表之上, 另加</strong>:</p><ul><li>[ ] 閘道與 MCP 映像以摘要值鎖定, 並訂閱 GitHub Security Advisories</li><li>[ ] 閘道管理端點只限管理者 IP</li><li>[ ] 每位使用者或每個應用各一把虛擬金鑰, 並設用量上限</li><li>[ ] 代理的寫入與刪除動作需要人工確認</li><li>[ ] 沙箱無網路, 並有資源上限</li><li>[ ] MCP 工具描述變更時重新審核</li><li>[ ] 金鑰輪替流程已準備, 並演練過一次</li></ul><h2 id="_9-4-硬體等級對應" tabindex="-1">9.4 硬體等級對應 <a class="header-anchor" href="#_9-4-硬體等級對應" aria-label="Permalink to &quot;9.4 硬體等級對應&quot;">​</a></h2><table tabindex="0"><thead><tr><th>等級</th><th>建議架構</th><th>備註</th></tr></thead><tbody><tr><td>A 無獨顯筆電</td><td>最小組合 (AnythingLLM 桌面版)</td><td>RAG 只用小型嵌入模型; 不跑代理</td></tr><tr><td>B 8 至 12GB 顯示卡</td><td>最小組合, 或精簡標準組合</td><td>嵌入模型放 CPU, 保留顯示記憶體</td></tr><tr><td>C Apple Silicon</td><td>16GB 用最小組合; 32GB 以上可用標準組合</td><td>依統一記憶體決定</td></tr><tr><td>D 16GB 顯示卡</td><td>標準組合</td><td>llama-swap 輪替對話與嵌入模型</td></tr><tr><td>E</td><td>標準組合; 小團隊可加 LangGraph</td><td>使用 Langfuse 須確認系統記憶體 32GB 以上</td></tr><tr><td>F</td><td>進階組合</td><td>有人能每週維運時才採用</td></tr></tbody></table><p>資料來源: 研究 2 第 12.4 節, 屬推論, 信心: 中.</p>`,38)])])}const g=a(l,[["render",e]]);export{k as __pageData,g as default};
